    Q('Balanced, but {} of it disappears next year.', 'Cuadra, pero {1} desaparece el próximo año.', '平衡了，但其中 {1} 明年就没了。', 'Zbilansowany, ale {1} zniknie za rok.'),
    Q('{} short', 'faltan {1}', '短缺 {1}', 'brakuje {1}'), Q('{} surplus', 'sobran {1}', '盈余 {1}', 'nadwyżka {1}'),
